create type public.app_role as enum ('admin', 'servant');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role public.app_role not null default 'servant', created_at timestamptz not null default now());
create table public.groups (id uuid primary key default gen_random_uuid(), name text not null unique, grade text not null default '', active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now());
create table public.group_servants (group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, primary key(group_id, user_id));
create table public.members (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete restrict, full_name text not null, phone text, family_phone text, address text, school text, notes text, active boolean not null default true, joined_at date not null default current_date, created_at timestamptz not null default now());
create table public.activities (id uuid primary key default gen_random_uuid(), name text not null unique, icon text not null default '⭐', color text not null default '#6366f1');
create table public.member_activities (member_id uuid not null references public.members(id) on delete cascade, activity_id uuid not null references public.activities(id) on delete cascade, primary key(member_id, activity_id));
create table public.attendance_sessions (id uuid primary key default gen_random_uuid(), attendance_date date not null unique, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), check (extract(dow from attendance_date) = 5));
create table public.attendance_records (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.attendance_sessions(id) on delete cascade, member_id uuid not null references public.members(id) on delete cascade, service_attended boolean not null default false, mass_attended boolean not null default false, mass_service boolean not null default false, confession boolean not null default false, phone_follow_up boolean not null default false, home_follow_up boolean not null default false, updated_by uuid not null references public.profiles(id), updated_at timestamptz not null default now(), unique(session_id, member_id));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.can_access_group(target_group uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_admin() or exists(select 1 from public.group_servants where group_id=target_group and user_id=auth.uid()) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.groups enable row level security; alter table public.group_servants enable row level security; alter table public.members enable row level security; alter table public.activities enable row level security; alter table public.member_activities enable row level security; alter table public.attendance_sessions enable row level security; alter table public.attendance_records enable row level security;
create policy "profiles readable" on public.profiles for select to authenticated using (true); create policy "admins manage profiles" on public.profiles for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "groups readable by access" on public.groups for select to authenticated using (public.can_access_group(id)); create policy "admins manage groups" on public.groups for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "assignments visible" on public.group_servants for select to authenticated using (user_id=auth.uid() or public.is_admin()); create policy "admins manage assignments" on public.group_servants for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "members by group access" on public.members for all to authenticated using (public.can_access_group(group_id)) with check (public.can_access_group(group_id));
create policy "activities readable" on public.activities for select to authenticated using (true); create policy "admins manage activities" on public.activities for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "member activities by group access" on public.member_activities for all to authenticated using (exists(select 1 from public.members m where m.id=member_id and public.can_access_group(m.group_id))) with check (exists(select 1 from public.members m where m.id=member_id and public.can_access_group(m.group_id)));
create policy "sessions readable" on public.attendance_sessions for select to authenticated using (true); create policy "sessions created by authenticated" on public.attendance_sessions for insert to authenticated with check (created_by=auth.uid()); create policy "sessions deleted by admins" on public.attendance_sessions for delete to authenticated using (public.is_admin());
create policy "records by group access" on public.attendance_records for all to authenticated using (exists(select 1 from public.members m where m.id=member_id and public.can_access_group(m.group_id))) with check (updated_by=auth.uid() and exists(select 1 from public.members m where m.id=member_id and public.can_access_group(m.group_id)));
